[
  {
    "id": 1,
    "source": "Von den eigenen Eltern verkauft –",
    "text": "فروخته‌شده توسط والدین خود –"
  },
  {
    "id": 2,
    "source": "Ich bin wütend auf meine Eltern,",
    "text": "من از دست والدینم عصبانی هستم،"
  },
  {
    "id": 3,
    "source": "aber was soll ich tun?",
    "text": "اما چه کار می‌توانم بکنم؟"
  },
  {
    "id": 4,
    "source": "Sie sagen: 'Was hätten wir denn sonst machen sollen?",
    "text": "آنها می‌گویند: «دیگر چه کار می‌توانستیم بکنیم؟"
  },
  {
    "id": 5,
    "source": "Wir mussten dich verheiraten'.",
    "text": "مجبور بودیم تو را شوهر بدهیم»"
  },
  {
    "id": 6,
    "source": "Bräute gegen Bargeld.",
    "text": "عروس در ازای پول نقد"
  },
  {
    "id": 7,
    "source": "Ich möchte in meiner eigenen Region heiraten.",
    "text": "من می‌خواهم در منطقه خودم ازدواج کنم"
  },
  {
    "id": 8,
    "source": "Wenn das nicht klappt, muss ich eine Frau von weit herholen.",
    "text": "اگر نشد، باید زنی را از راه دور بیاورم"
  },
  {
    "id": 9,
    "source": "Hier gibt es kaum Frauen.",
    "text": "اینجا به ندرت زنی پیدا می‌شود"
  },
  {
    "id": 10,
    "source": "Es kommen keine Ehen zustande.",
    "text": "هیچ ازدواجی صورت نمی‌گیرد"
  },
  {
    "id": 11,
    "source": "Der massive Frauenmangel im nordindischen Bundesstaat Haryana",
    "text": "کمبود شدید زنان در ایالت هاریانا در شمال هند"
  },
  {
    "id": 12,
    "source": "hat einen illegalen Markt geschaffen, auf dem verarmte Mädchen und Frauen",
    "text": "بازار غیرقانونی ایجاد کرده است که در آن دختران و زنان فقیر"
  },
  {
    "id": 13,
    "source": "gehandelt und zwangsverheiratet werden.",
    "text": "خرید و فروش شده و به ازدواج اجباری در می‌آیند"
  },
  {
    "id": 14,
    "source": "Ja, sie wollten 50.000 Rupien,",
    "text": "بله، آنها ۵۰ هزار روپیه می‌خواستند،"
  },
  {
    "id": 15,
    "source": "aber wir sind arm und haben nicht so viel Geld.",
    "text": "اما ما فقیر هستیم و این مقدار پول را نداریم"
  },
  {
    "id": 16,
    "source": "Am Ende akzeptierten sie 40.000.",
    "text": "در نهایت ۴۰ هزار را قبول کردند"
  },
  {
    "id": 17,
    "source": "Jahrzehnte geschlechtsselektiver Abtreibungen und Kindstötungen",
    "text": "دهه‌ها سقط جنین انتخابی بر اساس جنسیت و نوزادکشی"
  },
  {
    "id": 18,
    "source": "haben dazu geführt, dass der Bevölkerung Frauen fehlen.",
    "text": "باعث شده است که جمعیت با کمبود زنان مواجه شود"
  },
  {
    "id": 19,
    "source": "Sie haben mit Steinen nach mir geworfen. So war es.",
    "text": "آنها به سمت من سنگ پرتاب کردند. این‌طور بود"
  },
  {
    "id": 20,
    "source": "Warum haben sie das getan?",
    "text": "چرا این کار را کردند؟"
  },
  {
    "id": 21,
    "source": "Weil ich von außerhalb komme.",
    "text": "چون من از جای دیگری آمده‌ام"
  },
  {
    "id": 22,
    "source": "Jetzt sind die Folgen unübersehbar.",
    "text": "حالا پیامدها غیرقابل چشم‌پوشی هستند"
  },
  {
    "id": 23,
    "source": "Welchen Preis zahlt Haryana für die fehlenden Frauen?",
    "text": "هاریانا چه بهایی برای کمبود زنان می‌پردازد؟"
  },
  {
    "id": 24,
    "source": "Nargis Nariya kennt ihr genaues Alter nicht.",
    "text": "نرگس ناریا سن دقیق خود را نمی‌داند"
  },
  {
    "id": 25,
    "source": "Sie wuchs als eines von sechs Kindern in einer sehr armen Familie auf.",
    "text": "او به عنوان یکی از شش فرزند در خانواده‌ای بسیار فقیر بزرگ شد"
  }
]

