  {
    "id": 12,
    "source": "Ich hatte so viel Geld nicht.",
    "text": "من آنقدر پول نداشتم"
  },
  {
    "id": 13,
    "source": "Ich sagte, ich zahle es nach und nach zurück.",
    "text": "گفتم که آن را کم‌کم پس می‌دهم"
  },
  {
    "id": 14,
    "source": "45.000 Rupien, das sind umgerechnet 415 Euro.",
    "text": "۴۵ هزار روپیه، معادل ۴۱۵ یورو است"
  },
  {
    "id": 15,
    "source": "Unklar ist, wer wie viel von dem Geld bekam.",
    "text": "مشخص نیست چه کسی چه مقدار از این پول را دریافت کرده است"
  },
  {
    "id": 16,
    "source": "Nargis erlebt häusliche Gewalt.",
    "text": "نرگس خشونت خانگی را تجربه می‌کند"
  },
  {
    "id": 17,
    "source": "Über ihr eigenes Leben hat sie kaum Kontrolle.",
    "text": "او تقریباً هیچ کنترلی بر زندگی خودش ندارد"
  },
  {
    "id": 18,
    "source": "Wenn ich etwas Falsches mache, schlägt er mich.",
    "text": "اگر کار اشتباهی انجام دهم، مرا کتک می‌زند"
  },
  {
    "id": 19,
    "source": "Was gilt als falsch?",
    "text": "چه چیزی اشتباه محسوب می‌شود؟"
  },
  {
    "id": 20,
    "source": "Zum Beispiel das Handy anzufassen oder mir etwas zu kaufen.",
    "text": "مثلاً دست زدن به گوشی یا خریدن چیزی برای خودم"
  },
  {
    "id": 21,
    "source": "Hast du ein Handy?",
    "text": "آیا گوشی داری؟"
  },
  {
    "id": 22,
    "source": "Nein, ich habe kein Handy.",
    "text": "نه، من گوشی ندارم"
  },
  {
    "id": 23,
    "source": "Wenn ich eins hätte, würde er sagen: 'Sie spricht bestimmt\nmit anderen Männern.'",
    "text": "اگر داشتم، او می‌گفت: «حتماً دارد با\nمردهای دیگر صحبت می‌کند»"
  },
  {
    "id": 24,
    "source": "mit anderen Männern.'",
    "text": "با مردهای دیگر صحبت می‌کند»"
  },
  {
    "id": 25,
    "source": "Er könnte denken, ich hätte eine Affäre.",
    "text": "ممکن است فکر کند که من رابطه پنهانی دارم"
