  {
    "id": 13,
    "source": "Soghra wurde vor vier Monaten hierhergebracht,",
    "text": "صغری چهار ماه پیش به اینجا آورده شد"
  },
  {
    "id": 14,
    "source": "um Majidanas Sohn zu heiraten, einen Fabrikarbeiter.",
    "text": "تا با پسر مجیدانه که کارگر کارخانه است، ازدواج کند"
  },
  {
    "id": 15,
    "source": "Vor Jahren wurde Majidana selbst",
    "text": "سال‌ها پیش خود مجیدانه"
  },
  {
    "id": 16,
    "source": "aus dem 1600 Kilometer entfernten Dhubri in Assam hierhergebracht,",
    "text": "از دوبری در آسام که ۱۶۰۰ کیلومتر دورتر است، به اینجا آورده شد"
  },
  {
    "id": 17,
    "source": "um ihren inzwischen verstorbenen Mann zu heiraten.",
    "text": "تا با همسرش که اکنون فوت کرده، ازدواج کند"
