]

[
  {
    "id": 1,
    "source": "Alle fanden es gut, also stimmte ich auch zu.",
    "text": "همه موافق بودند، پس من هم قبول کردم"
  },
  {
    "id": 2,
    "source": "Majidana musste Geld an den Mittelsmann",
    "text": "مجیدانا مجبور شد به دلال پول بدهد"
  },
  {
    "id": 3,
    "source": "und an Soghras Familie zahlen, um sie hierherzubringen.",
    "text": "و به خانواده صغری پول بپردازد تا او را به اینجا بیاورند"
  },
  {
    "id": 4,
    "source": "Er nahm 40.000 Rupien.",
    "text": "او ۴۰ هزار روپیه گرفت"
  },
  {
    "id": 5,
    "source": "Ja, sie wollten 50.000 Rupien,",
    "text": "بله، آن‌ها ۵۰ هزار روپیه می‌خواستند"
  },
  {
    "id": 6,
    "source": "aber wir sind arm und haben nicht so viel Geld.",
    "text": "اما ما فقیر هستیم و آنقدر پول نداریم"
  },
  {
    "id": 7,
    "source": "Am Ende akzeptierten sie 40.000.",
    "text": "در نهایت ۴۰ هزار تا را قبول کردند"
  },
  {
    "id": 8,
    "source": "Ich wollte meinen Sohn einfach irgendwie verheiraten.",
    "text": "فقط می‌خواستم پسرم را به هر طریقی که شده داماد کنم"
  },
  {
    "id": 9,
    "source": "Also sagte ich: Nehmt das Geld.",
    "text": "برای همین گفتم: پول را بگیرید"
  },
  {
    "id": 10,
    "source": "Das ist ein weit verbreitetes Problem in Haryana.",
    "text": "این مشکلی است که در هاریانا بسیار رایج است"
  },
  {
    "id": 11,
    "source": "Es gibt nicht genug Frauen im heiratsfähigen Alter.",
    "text": "زنان کافی در سن ازدواج وجود ندارند"
  },
  {
    "id": 12,
    "source": "Ramkishan ist 28 Jahre alt und hat bisher keine passende Frau gefunden.",
    "text": "رامکیشان ۲۸ ساله است و تا به حال زن مناسبی پیدا نکرده است"
  },
  {
    "id": 13,
    "source": "Ich möchte in meiner Region heiraten.",
    "text": "من می‌خواهم در منطقه خودم ازدواج کنم"
  },
  {
    "id": 14,
    "source": "Wenn nicht, muss ich eine Frau von weit her holen.",
    "text": "اگر نشد، باید زنی را از راه دور بیاورم"
  },
  {
    "id": 15,
    "source": "Aber dann müssen Sie zahlen?",
    "text": "اما در آن صورت باید پول بپردازید؟"
  },
  {
    "id": 16,
    "source": "Ja, das kostet Geld.",
    "text": "بله، این کار هزینه دارد"
  },
  {
    "id": 17,
    "source": "Manche verlangen 15.000 Rupien, andere 16.000.",
    "text": "بعضی‌ها ۱۵ هزار روپیه می‌خواهند، بعضی دیگر ۱۶ هزار"
  },
  {
    "id": 18,
    "source": "Er sagt, es gebe eine mögliche Partnerin für ihn in Bihar,",
    "text": "او می‌گوید یک شریک احتمالی برایش در بیهار وجود دارد"
  },
  {
    "id": 19,
    "source": "1.000 Kilometer entfernt.",
    "text": "در ۱۰۰۰ کیلومتری اینجا"
  },
  {
    "id": 20,
    "source": "Und? Klappt es?",
    "text": "و؟ آیا جور می‌شود؟"
  },
  {
    "id": 21,
    "source": "Nein, es kommt nicht zustande.",
    "text": "نه، به نتیجه نمی‌رسد"
  },
  {
    "id": 22,
    "source": "Warum nicht?",
    "text": "چرا نه؟"
  },
  {
    "id": 23,
    "source": "Sie verlangen zu viel Geld.",
    "text": "آن‌ها پول زیادی می‌خواهند"
  },
  {
    "id": 24,
    "source": "Sie haben nicht so viel angespart?",
    "text": "شما آنقدر پس‌انداز ندارید؟"
  },
  {
    "id": 25,
    "source": "Nein.",
    "text": "نه"
  }
]

